function normalizeName(name: string): string {
  return name
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/^(1\.\s*fc\s+|fc\s+|cf\s+|afc\s+|sc\s+|ac\s+|bk\s+|ik\s+|ifk\s+|if\s+|sv\s+|vfl\s+|vfb\s+|tsv\s+|cd\s+|ud\s+|rc\s+)/i, '')
    .replace(/(\s+fc|\s+cf|\s+afc|\s+sc|\s+ac|\s+if|\s+bk|\s+ik|\s+ff|\s+sk|\s+is|\s+aif)$/i, '')
    .replace(/[^a-z0-9]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const dynamicLogoCache = new Map<string, string>();

export function getCleanTeamLogo(teamName: string, sport?: string): string | null {
  if (!teamName) return null;
  const rawKey = teamName.toLowerCase().trim();
  const cleanKey = normalizeName(teamName);

  if (dynamicLogoCache.has(cleanKey)) return dynamicLogoCache.get(cleanKey)!;
  if (dynamicLogoCache.has(rawKey)) return dynamicLogoCache.get(rawKey)!;

  if (STATIC_TEAM_LOGOS[rawKey]) return STATIC_TEAM_LOGOS[rawKey];
  if (STATIC_TEAM_LOGOS[cleanKey]) return STATIC_TEAM_LOGOS[cleanKey];

  // Partial substring matching for common variations (e.g. 'Man City' -> 'Manchester City')
  for (const [k, url] of Object.entries(STATIC_TEAM_LOGOS)) {
    if (k.length > 3 && (cleanKey.includes(k) || k.includes(cleanKey))) {
      return url;
    }
  }

  return null;
}

export function getTeamLeague(teamName: string): string | null {
  if (!teamName) return null;
  const rawKey = teamName.toLowerCase().trim();
  const cleanKey = normalizeName(teamName);

  if (TEAM_LEAGUES[rawKey]) return TEAM_LEAGUES[rawKey];
  if (TEAM_LEAGUES[cleanKey]) return TEAM_LEAGUES[cleanKey];

  for (const [k, league] of Object.entries(TEAM_LEAGUES)) {
    if (k.length > 3 && (cleanKey.includes(k) || k.includes(cleanKey))) {
      return league;
    }
  }

  return null;
}

/**
 * Returns a high-res uncropped badge URL.
 * If rawBadge is from streamed.pk (which provides 444x250 cropped strips that cut off top and bottom),
 * or is missing, it replaces it with the official 500x500 uncropped ESPN logo.
 */
export function cleanTeamBadgeUrl(rawBadge: string | undefined | null, teamName: string, sport?: string): string {
  const isStreamedCropped = Boolean(rawBadge && rawBadge.includes('streamed.pk/api/images/proxy'));
  const isPlaceholderAvatar = Boolean(rawBadge && rawBadge.includes('ui-avatars.com'));

  // Always attempt to get pristine uncropped 500x500 logo
  const cleanLogo = getCleanTeamLogo(teamName, sport);
  if (cleanLogo) {
    return cleanLogo;
  }

  // If rawBadge is valid and not cropped by streamed.pk proxy, use it
  if (rawBadge && !isStreamedCropped && !isPlaceholderAvatar) {
    return rawBadge;
  }

  // Never return streamed.pk cropped proxy images! Return clean high-res avatar
  return `https://ui-avatars.com/api/?name=${encodeURIComponent(teamName || 'T')}&background=1e1b4b&color=a78bfa&size=256&bold=true&format=png`;
}
